public class StreamBug {
    public static void main(String[] args) {
        List<String> nombres = List.of("Ana", "Bea", "Carlos");
        Stream<String> st = nombres.stream();

        // st.forEach(System.out::println);         // ❌ ERROR ①: consume el stream
