```java
public class TablaFrecuencias {
    public static void main(String[] args) {
        int[] datos = {3, 7, 3, 1, 7, 7, 5, 3, 1};

        // ✅ Array de contadores: índice 0..10 (posición = número)
        // freq[3] cuenta cuántas veces aparece el 3
        int[] freq = new int[11]; // Posiciones 0 a 10

        // ✅ Recorrer datos y usar cada valor como índice del contador
        for (int valor : datos) {
            freq[valor]++; // Incrementa el contador en la posición = valor
        }

        // ✅ Mostrar solo los que aparecen al menos una vez
        System.out.println("Tabla de frecuencias:");
        for (int i = 1; i <= 10; i++) {
            if (freq[i] > 0) {
                System.out.println(i + " → " + freq[i] + " veces");
            }
        }
    }
